    def countShapes(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        seen = [[False] * n for _ in range(m)]
        shapes = set()
        for r0 in range(m):
            for c0 in range(n):
                if grid[r0][c0] != 1 or seen[r0][c0]:
                    continue
                cells, stack = [], [(r0, c0)]
                seen[r0][c0] = True
                while stack:
                    r, c = stack.pop()
                    cells.append((r - r0, c - c0))
                    for a, b in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                        if 0 <= a < m and 0 <= b < n and grid[a][b] == 1 and not seen[a][b]:
                            seen[a][b] = True
                            stack.append((a, b))
                shapes.add(tuple(sorted(cells)))
        return len(shapes)

