function countShapes(grid: number[][]): number {
  const m = grid.length, n = grid[0].length;
  const seen = grid.map(row => row.map(() => false));
  const shapes = new Set<string>();
  const dirs: [number, number, string][] = [[1, 0, "D"], [-1, 0, "U"], [0, 1, "R"], [0, -1, "L"]];
  for (let r0 = 0; r0 < m; r0++)
    for (let c0 = 0; c0 < n; c0++) {
      if (grid[r0][c0] !== 1 || seen[r0][c0]) continue;
      const path: string[] = ["S"];
      seen[r0][c0] = true;
      // explicit stack of [row, col, next direction index] to avoid deep recursion
      const stack: number[][] = [[r0, c0, 0]];
      while (stack.length) {
        const top = stack[stack.length - 1];
        if (top[2] === 4) { stack.pop(); path.push("B"); continue; }
        const [dr, dc, ch] = dirs[top[2]++];
        const a = top[0] + dr, b = top[1] + dc;
        if (a >= 0 && b >= 0 && a < m && b < n && grid[a][b] === 1 && !seen[a][b]) {
          seen[a][b] = true;
          path.push(ch);
          stack.push([a, b, 0]);
        }
      }
      shapes.add(path.join(""));
    }
  return shapes.size;
}

